INSERT INTO "questions" VALUES (1,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "questions" VALUES (2,'Create a directory named ''backup'' and move all ''.log'' files into it.','File manipulation',1,'mkdir backup && mv *.log backup/','[ -d backup ] && [ -f backup/app.log ]','touch app.log sys.log notes.txt','rm -rf backup app.log sys.log notes.txt','gemini');
INSERT INTO "questions" VALUES (3,'Extract the second column (usernames) from ''data.csv'' and save to ''users.txt''.','Text processing',2,'cut -d'','' -f2 data.csv > users.txt','grep -q ''alice'' users.txt','printf ''id,user\n1,alice\n2,bob'' > data.csv','rm -f data.csv users.txt','gemini');
INSERT INTO "questions" VALUES (4,'Change permissions of ''config.sh'' so the owner has full access (7) and others have only read (4).','Permissions',2,'chmod 744 config.sh','stat -c ''%a'' config.sh | grep -q ''744''','touch config.sh','rm -f config.sh','gemini');
INSERT INTO "questions" VALUES (5,'Create a group named ''devs'' and change the group ownership of ''project.txt'' to it.','Users & Groups',3,'groupadd devs && chgrp devs project.txt','stat -c ''%G'' project.txt | grep -q ''devs''','touch project.txt','rm -f project.txt && groupdel devs','gemini');
INSERT INTO "questions" VALUES (6,'Find the PID of the process ''dummy_app'' and save it to ''pid.txt''.','Processes',3,'pgrep dummy_app > pid.txt','pgrep dummy_app | diff - pid.txt','sleep 100 & exec -a dummy_app sleep 100 &','pkill -f dummy_app && rm -f pid.txt','gemini');
INSERT INTO "questions" VALUES (7,'Compress the ''logs'' folder into ''archive.tar.gz''.','Archiving',2,'tar -czf archive.tar.gz logs/','tar -ztf archive.tar.gz | grep -q ''logs/''','mkdir logs && touch logs/1.log','rm -rf logs archive.tar.gz','gemini');
INSERT INTO "questions" VALUES (8,'Check if ''127.0.0.1'' responds to 1 ping packet and save output to ''ping.txt''.','Network',1,'ping -c 1 127.0.0.1 > ping.txt','grep -q ''1 packets transmitted'' ping.txt','rm -f ping.txt','rm -f ping.txt','gemini');
INSERT INTO "questions" VALUES (9,'Count occurrences of ''ERROR'' in ''sys.log'' and save the number to ''count.txt''.','Text processing',2,'grep -c ''ERROR'' sys.log > count.txt','grep -q ''2'' count.txt','printf ''ERROR\nINFO\nERROR'' > sys.log','rm -f sys.log count.txt','gemini');
INSERT INTO "questions" VALUES (10,'Extract ''data.zip'' into the current directory.','Compression',2,'unzip data.zip','[ -f note.txt ]','echo ''test'' > note.txt && zip data.zip note.txt && rm note.txt','rm -f data.zip note.txt','gemini');
INSERT INTO "questions" VALUES (11,'Count the number of lines in customer.csv','Text processing',1,'wc -l < customer.csv','[[ $(wc -l < customer.csv) -eq 4 ]]','printf ''Row1\nRow2\nRow3\nRow4'' > customer.csv','rm -f customer.csv','eval-25');
INSERT INTO "questions" VALUES (12,'Print the last 3 lines from customer.csv','Text processing',1,'tail -n 3 customer.csv','# Internal App Logic Check','printf ''1\n2\n3\n4\n5'' > customer.csv','rm -f customer.csv','eval-25');
INSERT INTO "questions" VALUES (13,'Print only the 2nd column of customer.csv','Text processing',2,'cut -d'','' -f2 customer.csv','# Internal App Logic Check','printf ''1,Alice,Dev\n2,Bob,Ops'' > customer.csv','rm -f customer.csv','eval-25');
INSERT INTO "questions" VALUES (14,'Print the comments in code.js','Text processing',2,'grep ''//'' code.js','# Internal App Logic Check','printf ''const a=1;\n// comment\nconst b=2;'' > code.js','rm -f code.js','eval-25');
INSERT INTO "questions" VALUES (15,'Print the code but this time exclude the comments (lines that start with "//").','Text processing',2,'grep -v ''//'' code.js','# Internal App Logic Check','printf ''const a=1;\n// comment'' > code.js','rm -f code.js','eval-25');
INSERT INTO "questions" VALUES (16,'Show all 4-letter words in the file code.js','Text processing',3,'grep -oE ''\b[a-zA-Z]{4}\b'' code.js','# Internal App Logic Check','printf ''this is a test code'' > code.js','rm -f code.js','eval-25');
INSERT INTO "questions" VALUES (17,'Find the number of unique values in the 3nd column of customer.csv','Text processing',3,'cut -d'','' -f3 customer.csv | sort | uniq | wc -l','# Internal App Logic Check','printf ''1,A,USA\n2,B,UK\n3,C,USA'' > customer.csv','rm -f customer.csv','eval-25');
